        // alice, alicia, bob = 3개
        let t5 = assert_eq_i32(count2, 3, "range [alice,bob] count=3");
        print_result(t5);

        // 삭제
        let del_ok = si.str_delete("bob", 2);
        let t6 = assert_true(del_ok, "delete bob ok");
        print_result(t6);

        let t7 = assert_eq_i32(si.entry_count, 3, "3 entries after delete");
        print_result(t7);

        print(si.str_stats());
    }

