        let s = schema.schema_new("test");
        s.schema_add_col("id", schema.COL_TYPE_INT, false);
        s.schema_add_col("val", schema.COL_TYPE_INT, false);

        let t = schema.table_new(s);

        // 10개 행 삽입 (val: 10, 20, 30, ..., 100)
        let i = 0;
        for i = 0; i < 10; i = i + 1 {
            let row = schema.record_new();
            row.int_vals[0] = i64(i + 1);
            row.int_vals[1] = i64((i + 1) * 10);
            t.table_insert(row);
        }

        // 통계 수집
        let stats = planner.stats_build(&t);
        let t1 = assert_eq_i32(stats.row_count, 10, "stats row_count=10");
        print_result(t1);

        // 쿼리 생성
        let q = query.query_table(t);
        q.where_int(1, query.OP_EQ, 50);  // val == 50

        // 계획 생성 (인덱스 없음 → 풀스캔)
        let plan = planner.plan_query(&q, &stats, false, false);
        let t2 = assert_eq_i32(plan.plan_type, planner.PLAN_FULL_SCAN, "no index → full scan");
        print_result(t2);

        let t3 = assert_eq_i32(plan.cost, 10, "cost=10 (row_count)");
        print_result(t3);

        // 범위 쿼리
        let q2 = query.query_table(t);
        q2.where_int(1, query.OP_GT, 50);  // val > 50
        let plan2 = planner.plan_query(&q2, &stats, false, false);
        let t4 = assert_true(plan2.plan_type == planner.PLAN_FULL_SCAN, "range query → full scan");
        print_result(t4);

        print("Planner tests completed");
